// Website sample collection: ten stories.
const STORIES = [{"id": "pyramid", "contentID": "pyramid-en", "version": 1, "language": "en", "category": "history", "label": "HISTORY · DISCOVERY", "title": "The mountain people made", "plainTitle": "The mountain people made", "description": "Before it became a wonder of the world, the Great Pyramid was a problem waiting to be solved.", "deck": "Before it became a wonder of the world, the Great Pyramid was a problem waiting to be solved.", "place": "History · Discovery", "minutes": 3, "coverURL": "content/pyramid-en/v1/cover.jpg", "alt": "Illustration for The mountain people made", "note": "A true-history sample. The opening landscape is an imaginative scene-setting description. Archaeologists still debate the exact construction methods.", "sources": [["Smithsonian: The Egyptian Pyramid", "https://www.si.edu/spotlight/ancient-egypt/pyramid"]], "chapters": [{"title": "A shape against the sky", "paragraphs": ["Picture the Nile slipping past green fields, with the dry desert stretching beyond them. Above that desert stands a shape so large that it seems to belong to the landscape itself: a pyramid.", "About 4,500 years ago, Egypt’s king Khufu ordered the Great Pyramid built at Giza. It was intended as his tomb. In ancient Egyptian belief, preparing for life after death was an important task. For a king, that preparation could become a whole building project.", "But an enormous idea does not lift a single stone. The people who built the pyramid had to turn an ambition into thousands of practical jobs."], "paragraphIDs": ["pyramid-en-c1-p1", "pyramid-en-c1-p2", "pyramid-en-c1-p3"]}, {"title": "A mountain of small jobs", "paragraphs": ["Stone had to be cut, moved, and carefully placed. Teams needed tools, food, and places to work. Builders had to keep the growing structure level and its sides pointing in the right directions.", "The pyramid narrowed as it rose. Each layer supported the next, carrying its weight down toward the broad base. From the ground, the shape looks simple; making that shape from heavy blocks required organization and patient craftsmanship.", "Marks left by workers on some stones preserve the names of work teams. Those small traces remind us that this huge monument was made by people working together."], "paragraphIDs": ["pyramid-en-c2-p1", "pyramid-en-c2-p2", "pyramid-en-c2-p3"]}, {"title": "The people inside the wonder", "paragraphs": ["When it was finished, pale limestone covered the pyramid’s outside. Much of that smooth casing has since disappeared, leaving the stepped stone surface we often see today.", "We know the pyramid was built, and we can study the stones. We do not yet know every detail of how the builders raised them. Different ramp designs are among the possibilities researchers investigate.", "The wonder is more than its size. It is the cooperation inside it: countless separate jobs fitted into one great plan. A mountain of stone began with people solving one problem, and then the next."], "paragraphIDs": ["pyramid-en-c3-p1", "pyramid-en-c3-p2", "pyramid-en-c3-p3"]}], "audio": null}, {"id": "earth", "contentID": "earth-en", "version": 1, "language": "en", "category": "history", "label": "HISTORY · DISCOVERY", "title": "The shadow that measured a world", "plainTitle": "The shadow that measured a world", "description": "Eratosthenes could not travel around the whole Earth. So he let the Sun help him.", "deck": "Eratosthenes could not travel around the whole Earth. So he let the Sun help him.", "place": "History · Discovery", "minutes": 3, "coverURL": "content/earth-en/v1/cover.jpg", "alt": "Illustration for The shadow that measured a world", "note": "A true-discovery sample. Ancient accounts simplify the geometry; the cities are not exactly on the same north–south line. The modern length of the ancient unit is uncertain.", "sources": [["Smithsonian: Measurement of the Earth", "https://www.americanhistory.si.edu/ne/collections/object/nmah_694634"], ["American Physical Society: Eratosthenes Measures Earth", "https://www.aps.org/apsnews/2006/06/eratosthenes-measures-earth"]], "chapters": [{"title": "Two cities, one Sun", "paragraphs": ["In the Egyptian city of Alexandria, a scholar named Eratosthenes wanted to know how far it was around Earth. He lived more than two thousand years ago, long before anyone could photograph our planet from space.", "He learned of an unusual observation in Syene, far to the south. At noon near the summer solstice, sunlight could shine straight down into a well. The Sun was almost directly overhead.", "In Alexandria at the same time, an upright object still cast a shadow. The same Sun was lighting both places. The difference held a clue."], "paragraphIDs": ["earth-en-c1-p1", "earth-en-c1-p2", "earth-en-c1-p3"]}, {"title": "A curve you can measure", "paragraphs": ["Imagine two tiny sticks standing on a ball, some distance apart. Because the surface curves, the sticks point in slightly different directions. Sunlight arriving from far away meets them at different angles.", "Eratosthenes measured the angle revealed by the shadow at Alexandria. It was about one fiftieth of a full circle. In a simplified model, the stretch from Syene to Alexandria therefore covered about one fiftieth of the way around Earth.", "He also needed the distance between the cities. With that estimate, he could multiply by fifty to work out the whole circle. One small shadow had become a measuring tool for an entire planet."], "paragraphIDs": ["earth-en-c2-p1", "earth-en-c2-p2", "earth-en-c2-p3"]}, {"title": "A bigger view", "paragraphs": ["The old accounts give the distance in a unit called a stadion. Because its exact length is uncertain, we cannot translate his result into one perfectly agreed modern number. The clever method, however, is clear.", "He did not discover that Earth was round; other thinkers already understood that. He worked out a way to measure its size.", "A shadow, a distance, and an idea were enough to reach beyond what one person could see. The world was vast, but it could be understood, piece by careful piece."], "paragraphIDs": ["earth-en-c3-p1", "earth-en-c3-p2", "earth-en-c3-p3"]}], "audio": null}, {"id": "moon", "contentID": "moon-en", "version": 1, "language": "en", "category": "science", "label": "SPACE · SCIENCE", "title": "The night the Moon came closer", "plainTitle": "The night the Moon came closer", "description": "Three travelers left Earth. Two would land on the Moon. All three needed a way home.", "deck": "Three travelers left Earth. Two would land on the Moon. All three needed a way home.", "place": "Space · Science", "minutes": 3, "coverURL": "content/moon-en/v1/cover.jpg", "alt": "Illustration for The night the Moon came closer", "note": "A true-spaceflight sample. “The night” is a story title; the Moon landing occurred at different local times around Earth. Illustrations are imaginative interpretations.", "sources": [["NASA: Apollo 11 Mission Overview", "https://www.nasa.gov/history/apollo-11-mission-overview/"], ["NASA JPL: The Apollo Moon landing", "https://www.jpl.nasa.gov/edu/resources/teachable-moment/celebrate-the-50th-anniversary-of-nasas-apollo-moon-landing-with-educational-resources-and-projects-for-kids/"]], "chapters": [{"title": "A journey with three travelers", "paragraphs": ["On July 16, 1969, a Saturn V rocket lifted Neil Armstrong, Buzz Aldrin, and Michael Collins away from Earth. Their mission was called Apollo 11. Ahead lay the Moon, a world with no air to breathe and no oceans to cross.", "Their spacecraft had different parts for different jobs. Columbia was the command module, where the astronauts could travel together. A service module supplied important things such as power and propulsion. Eagle, the lunar module, was built for the landing.", "Taking every part down to the Moon would have meant carrying extra weight. The smaller Eagle could do the landing job while Columbia stayed in orbit."], "paragraphIDs": ["moon-en-c1-p1", "moon-en-c1-p2", "moon-en-c1-p3"]}, {"title": "Eagle finds a place to rest", "paragraphs": ["On July 20, Armstrong and Aldrin separated from Columbia in Eagle. Collins remained above, circling the Moon. His part of the journey mattered just as much: the landing crew would need to meet him again.", "Eagle used its rocket engine to slow its descent. As the surface came close, Armstrong guided it away from an area with large rocks toward a clearer landing spot.", "The spacecraft touched down in the Sea of Tranquility. Despite its name, there was no water there: it was a broad, dark region of the Moon’s surface. Soon, Armstrong and then Aldrin stepped outside. Their suits supplied the air their bodies needed."], "paragraphIDs": ["moon-en-c2-p1", "moon-en-c2-p2", "moon-en-c2-p3"]}, {"title": "The road back home", "paragraphs": ["The astronauts collected rock samples and set up scientific equipment. But a successful landing was only part of the adventure. They still had to leave.", "Eagle had two stages. Its lower part stayed on the Moon, while its upper part lifted off with the two astronauts. Leaving weight behind made the return possible. They joined Collins and Columbia in orbit.", "On July 24, the crew splashed down in the Pacific Ocean. Three people had traveled together, two had walked on another world, and all three had returned. A daring dream had worked because each small part had a careful job."], "paragraphIDs": ["moon-en-c3-p1", "moon-en-c3-p2", "moon-en-c3-p3"]}], "audio": null}, {"id": "fireflies", "contentID": "fireflies-en", "version": 1, "language": "en", "category": "nature", "label": "NATURE · ANIMALS", "title": "The little lights in the dark", "plainTitle": "The little lights in the dark", "description": "A tiny flash in the darkness is more than a pretty light. It can be a message.", "deck": "A tiny flash in the darkness is more than a pretty light. It can be a message.", "place": "Nature · Animals", "minutes": 3, "coverURL": "content/fireflies-en/v1/cover.jpg", "alt": "Illustration for The little lights in the dark", "note": "A natural-science sample with an imagined garden setting. Firefly behavior varies between species; not all adult fireflies flash.", "sources": [["Smithsonian Science Education Center: Expedition Insects", "https://ssec.si.edu/sites/default/files/other/insects/Expedition%20Insects-.pdf"], ["Smithsonian: How animals communicate", "https://ssec.si.edu/communication"]], "chapters": [{"title": "The garden wakes up", "paragraphs": ["Imagine a summer garden as daylight fades. The bright colors soften, leaves become silhouettes, and a tiny light flickers above the grass. Then another glows nearby.", "Those little lanterns belong to fireflies. Despite their name, they are beetles. Many kinds can produce light in special organs near the end of their bodies.", "A lamp needs electricity from somewhere outside it. A firefly carries the ingredients for its light within its own body. The glow begins with chemistry."], "paragraphIDs": ["fireflies-en-c1-p1", "fireflies-en-c1-p2", "fireflies-en-c1-p3"]}, {"title": "A lantern made of life", "paragraphs": ["Inside a firefly, a substance called luciferin takes part in a reaction involving oxygen. An enzyme called luciferase helps the reaction happen. Energy is released as light.", "Making light through a living chemical process is called bioluminescence. The word sounds large, but the idea fits in a small beetle: life making a glow.", "The flashing can carry information. Many fireflies use patterns of light to find mates. A flash followed by a pause can be part of a signal; another firefly may answer. The dark garden becomes a place where light helps living things communicate."], "paragraphIDs": ["fireflies-en-c2-p1", "fireflies-en-c2-p2", "fireflies-en-c2-p3"]}, {"title": "Messages in the evening", "paragraphs": ["Different species have different habits. Some flash, some shine more steadily, and some adult fireflies do not use a visible light display at all. Nature has many ways of solving the same problem.", "Imagine watching quietly from a path. Instead of seeing random sparks, you might begin to notice patterns: a glow, a pause, another glow. You are looking at a small piece of animal communication.", "The garden has not turned into a fairy tale. It is full of real living things doing remarkable things. Sometimes a little knowledge makes an ordinary evening feel even more wonderful."], "paragraphIDs": ["fireflies-en-c3-p1", "fireflies-en-c3-p2", "fireflies-en-c3-p3"]}], "audio": null}, {"id": "the-clock-that-crossed-the-ocean-en", "contentID": "the-clock-that-crossed-the-ocean-en", "version": 1, "language": "en", "category": "history", "label": "HISTORY", "title": "The Clock That Crossed the Ocean", "plainTitle": "The Clock That Crossed the Ocean", "description": "In the early eighteenth century, a ship could leave England, sail for weeks, and still have a dangerous uncertainty hanging over its deck.", "deck": "In the early eighteenth century, a ship could leave England, sail for weeks, and still have a dangerous uncertainty hanging over its deck.", "place": "History", "minutes": 7, "coverURL": "content/the-clock-that-crossed-the-ocean-en/v1/cover.jpg", "alt": "Illustration for The Clock That Crossed the Ocean", "note": "Royal Museums Greenwich: Harrison and the longitude problem; Royal Museums Greenwich: H4; Science Museum Group: John Harrison. The time-and-longitude example is an explanatory calculation, not an invented historical voyage.", "sources": [["Royal Museums Greenwich: Harrison and the longitude problem", "https://www.rmg.co.uk/stories/time/harrisons-clocks-longitude-problem"], ["Royal Museums Greenwich: H4", "https://www.rmg.co.uk/collections/objects/rmgc-object-79142"], ["Science Museum Group: John Harrison", "https://collection.sciencemuseumgroup.org.uk/people/ap21350/harrison-john"]], "chapters": [{"title": "The Clock That Crossed the Ocean", "paragraphs": ["In the early eighteenth century, a ship could leave England, sail for weeks, and still have a dangerous uncertainty hanging over its deck.", "Its sailors might know how far north or south they were. On a clear day, they could measure the height of the Sun above the horizon. At night, certain stars helped them find their latitude.", "But their position east or west was much harder to discover.", "That position was called longitude. Without it, a captain could mistake open water for the approach to a coast, or sail past an island carrying the fresh water his crew desperately needed.", "The ocean had no milestones. A ship's speed could be estimated, but currents carried it sideways and storms forced it off course. Small errors collected over a long voyage until the position marked on a chart was far from the ship's real position.", "In 1714, the British government offered large rewards for a practical way to find longitude at sea. The greatest reward was twenty thousand pounds, an extraordinary sum.", "Some astronomers searched for an answer in the Moon and stars.", "A carpenter named John Harrison searched inside a clock.", "Harrison had grown up working with wood. He learned to build clocks, and he paid close attention to the things that made them lose time. A tiny change repeated thousands of times could turn a good clock into a bad one.", "The connection between a clock and a ship's position came from Earth's daily turn.", "Earth turns through a full circle of 360 degrees in about twenty-four hours. In one hour, it turns fifteen degrees.", "If a sailor knew the time at a chosen home port and compared it with the local time at the ship, the difference would reveal how far east or west the ship had travelled.", "Suppose the Sun reached its highest point over the ship when a clock keeping home time showed two in the afternoon. Noon had arrived at the home port two hours earlier. The ship was about thirty degrees west of that port.", "The idea was clear. Making a clock that could do the job was another matter.", "A clock ashore stood in a relatively steady place. A ship rolled, pitched, shuddered, and sometimes struck waves hard enough to throw people off their feet.", "Many ordinary clocks depended on a swinging pendulum. A pendulum that worked well in a house behaved very differently on a moving deck.", "Temperature created another difficulty. Metal parts expanded in warm weather and contracted in cold weather. Those changes altered the timing of a mechanism, even when they were too small to see.", "Sea air brought dampness and salt. Oil changed as it aged. The friction between moving parts could change too.", "Harrison had to solve several problems at once, because a clock that failed in only one of them could send a ship miles from its expected position.", "His first large sea clock, later called H1, did not look like a pocket watch. It was a complicated machine with brass wheels and linked balances. Instead of relying on an ordinary pendulum, Harrison arranged moving parts to counter some of the effects of the ship's motion.", "In 1736, H1 travelled to Lisbon for a sea trial.", "It performed well enough to encourage further work, but Harrison did not regard it as finished. He began another timekeeper, and then another.", "Years passed.", "Each machine solved some problems while revealing others. Harrison's work required more than assembling wheels. He had to notice an error, understand what caused it, change the design, and test the result over long periods.", "Eventually, his approach changed dramatically.", "The fourth timekeeper, H4, was much smaller than the earlier machines. It looked like an oversized silver watch. Inside its case, carefully made parts worked together at a rapid, regular pace.", "Its size mattered. A useful instrument had to travel, and a small timekeeper was easier to place aboard a ship than a large experimental machine.", "But appearance was not proof. H4 had to cross an ocean.", "In 1761, Harrison's son William took it on a voyage to Jamaica. William looked after the instrument while the ship carried it through the conditions that had defeated other clocks.", "The timekeeper kept remarkably close to the required time. Its error was small enough to show that Harrison's method could determine longitude with the accuracy demanded by the highest reward.", "That did not end the argument.", "The Board of Longitude needed to know whether another instrument could be made to work equally well. A single extraordinary watch might prove a principle without yet providing a reliable system for an entire navy.", "There were also disagreements about further trials, payment, and how fully Harrison should reveal the details of his invention.", "Harrison, now an old man, had spent decades on the problem. To him, the successful crossing was powerful evidence. To the officials, testing and reproduction still mattered.", "Other craftsmen examined the design. Larcum Kendall made a copy of H4, known as K1. That timekeeper later travelled with James Cook and helped demonstrate the value of accurate timekeeping on long voyages.", "Harrison eventually received substantial payments, including a final award arranged through Parliament in 1773. His reward did not arrive as one simple victory on the day his watch returned from Jamaica.", "Nor did every ship immediately receive a perfect sea watch. Early marine timekeepers were expensive and difficult to make. Astronomical methods remained useful, and improvements in manufacturing took time.", "Gradually, accurate marine clocks became more widely available.", "A captain could compare the ship's local time with the time kept by an instrument carried from home. An invisible difference between two moments became a distance on a chart.", "Harrison's surviving timekeepers can still be seen at Greenwich. The great brass balances of his early machines and the compact silver case of H4 belong to the same long effort.", "The smallest part of that effort was measured in seconds.", "Its result was measured across oceans."], "paragraphIDs": ["the-clock-that-crossed-the-ocean-en-p-af4784dea148", "the-clock-that-crossed-the-ocean-en-p-5f53bfcedf56", "the-clock-that-crossed-the-ocean-en-p-66bde42a0057", "the-clock-that-crossed-the-ocean-en-p-0e529335a7e0", "the-clock-that-crossed-the-ocean-en-p-bbc51db4fd5f", "the-clock-that-crossed-the-ocean-en-p-6ef424fcfd49", "the-clock-that-crossed-the-ocean-en-p-3fc859bf4ff8", "the-clock-that-crossed-the-ocean-en-p-ea51275f213f", "the-clock-that-crossed-the-ocean-en-p-73e11783c483", "the-clock-that-crossed-the-ocean-en-p-414388422701", "the-clock-that-crossed-the-ocean-en-p-7b890f01213a", "the-clock-that-crossed-the-ocean-en-p-173e1f0cb226", "the-clock-that-crossed-the-ocean-en-p-d358cd0cba15", "the-clock-that-crossed-the-ocean-en-p-3f32f4f5176d", "the-clock-that-crossed-the-ocean-en-p-381f60e82d73", "the-clock-that-crossed-the-ocean-en-p-bc0b8533739c", "the-clock-that-crossed-the-ocean-en-p-3d919012e272", "the-clock-that-crossed-the-ocean-en-p-679e2ab75245", "the-clock-that-crossed-the-ocean-en-p-99525bc0d704", "the-clock-that-crossed-the-ocean-en-p-c637194c1fb5", "the-clock-that-crossed-the-ocean-en-p-214bed1c396b", "the-clock-that-crossed-the-ocean-en-p-69603b05ee1a", "the-clock-that-crossed-the-ocean-en-p-2a423bebc5c0", "the-clock-that-crossed-the-ocean-en-p-5736e885b994", "the-clock-that-crossed-the-ocean-en-p-239f40c3f38d", "the-clock-that-crossed-the-ocean-en-p-52f589504126", "the-clock-that-crossed-the-ocean-en-p-250781771f00", "the-clock-that-crossed-the-ocean-en-p-13706eb370f4", "the-clock-that-crossed-the-ocean-en-p-295ae08bb424", "the-clock-that-crossed-the-ocean-en-p-6bbc566351c8", "the-clock-that-crossed-the-ocean-en-p-79070511f3a7", "the-clock-that-crossed-the-ocean-en-p-d0bdbbfc9f21", "the-clock-that-crossed-the-ocean-en-p-a020f9dce8ae", "the-clock-that-crossed-the-ocean-en-p-46938dd7c187", "the-clock-that-crossed-the-ocean-en-p-f078dbeb2968", "the-clock-that-crossed-the-ocean-en-p-784ad1726f6a", "the-clock-that-crossed-the-ocean-en-p-b7d49652ef67", "the-clock-that-crossed-the-ocean-en-p-e4dffc4e2a8b", "the-clock-that-crossed-the-ocean-en-p-b7a878bcb950", "the-clock-that-crossed-the-ocean-en-p-51531e06995b", "the-clock-that-crossed-the-ocean-en-p-85c4d0723127", "the-clock-that-crossed-the-ocean-en-p-746c62627f22"]}], "audio": null}, {"id": "the-bicycle-makers-who-taught-a-machine-to-fly-en", "contentID": "the-bicycle-makers-who-taught-a-machine-to-fly-en", "version": 1, "language": "en", "category": "history", "label": "HISTORY", "title": "The Bicycle Makers Who Taught a Machine to Fly", "plainTitle": "The Bicycle Makers Who Taught a Machine to Fly", "description": "In Dayton, Ohio, Wilbur and Orville Wright spent their working days repairing bicycles.", "deck": "In Dayton, Ohio, Wilbur and Orville Wright spent their working days repairing bicycles.", "place": "History", "minutes": 7, "coverURL": "content/the-bicycle-makers-who-taught-a-machine-to-fly-en/v1/cover.jpg", "alt": "Illustration for The Bicycle Makers Who Taught a Machine to Fly", "note": "National Park Service: The Wright brothers; National Park Service: The first flight; National Park Service: The fourth flight.", "sources": [["National Park Service: The Wright brothers", "https://www.nps.gov/articles/wright-brothers.htm"], ["National Park Service: The first flight", "https://www.nps.gov/wrbr/learn/historyculture/thefirstflight.htm"], ["National Park Service: The fourth flight", "https://www.nps.gov/places/000/fourth-flight-landing.htm"]], "chapters": [{"title": "The Bicycle Makers Who Taught a Machine to Fly", "paragraphs": ["In Dayton, Ohio, Wilbur and Orville Wright spent their working days repairing bicycles.", "A bicycle had wheels, chains, bearings, and a rider who had to keep it balanced. If a rider leaned carelessly or turned badly, a perfectly good machine could fall over.", "That was an important problem to understand for two men who wanted to build an aircraft.", "By the end of the nineteenth century, many inventors were trying to fly. Balloons could rise, and gliders could carry people through the air for short distances. But a practical powered aircraft needed to do more than leave the ground.", "It had to stay under control.", "A machine that lifted a person into the sky but could not turn safely or recover from a tilt was a danger rather than a useful invention.", "The Wright brothers studied earlier experiments, including the work of Otto Lilienthal, who had made many gliding flights before dying after a crash in 1896. They corresponded with the experienced aviation experimenter Octave Chanute.", "Then they began making their own tests.", "For their outdoor work, they chose the coast of North Carolina. Near Kitty Hawk and Kill Devil Hills, wind could provide lift, and broad sandy ground offered a softer place to land than a city street.", "Getting there from Ohio required transporting equipment to a remote coast. The brothers worked away from their bicycle shop, living beside the dunes while salt air and blowing sand reached their tools.", "Their early gliders had two wings, one above the other.", "The wings were curved because their shape helped moving air produce lift. But lift alone did not solve the problem of balance.", "An aircraft could tip in three different ways. Its nose could rise or fall. One wing could tilt lower than the other. Its nose could swing to the left or right.", "The brothers needed control over all three movements.", "They placed a movable surface in front of the wings to control the nose's up-and-down movement. To control the side-to-side tilt, they developed wing warping.", "The tips of the wings could be twisted so that the two sides met the air at different angles. One side then produced more lift than the other, helping the pilot correct a tilt.", "This made the wings active parts of the steering system.", "But the tests did not produce all the results the brothers expected.", "In 1901, their glider gave less lift than calculations had suggested. It also behaved badly during some turns. Simply building a larger wing would not explain why the calculations were wrong.", "They returned to Dayton and built a wind tunnel.", "It was a wooden box with a fan that sent air over small model wings. Inside, measuring devices allowed the brothers to compare different shapes.", "The tunnel let them test many designs without building a full aircraft for each one. A wing could be changed, placed in the moving air, and measured against another.", "They studied both lift and drag. Lift helped keep an aircraft up. Drag resisted its movement through the air. A wing that produced useful lift while creating too much drag might leave an engine unable to move the aircraft fast enough.", "Their measurements gave them better information than the tables they had originally relied on.", "In 1902, they returned to North Carolina with a much improved glider.", "There was still a steering difficulty. When the wings were warped for a turn, the two sides did not only produce different amounts of lift. They also produced different amounts of drag. That could swing the nose in an unwanted direction.", "A movable rear rudder helped control this movement. Used together with wing warping, it allowed the aircraft to turn more effectively.", "The brothers made hundreds of gliding flights.", "They were learning how to fly before adding an engine.", "For the powered machine, they needed an engine light enough to carry but strong enough to drive propellers. Their mechanic, Charlie Taylor, helped build one when available engines did not suit their needs.", "The propellers were another engineering problem.", "A propeller was not simply a paddle pushing against air. Each blade worked like a wing moving along a turning path. Its shape had to suit the different speeds at different distances from the centre.", "The brothers used what they had learned about wings to design efficient wooden propellers. Chains connected the engine to two propellers behind the aircraft.", "On 17 December 1903, the machine stood on a launching rail at Kill Devil Hills.", "The wind was strong and the weather cold. The pilot would lie on the lower wing rather than sit in an enclosed cabin. There were no comfortable seats, windscreen, or passenger aisle.", "Orville made the first flight.", "The aircraft left the rail and travelled 120 feet, about 37 metres, in twelve seconds. Its movement was uneven, but it had carried its pilot in powered, controlled flight.", "Three more flights followed. The brothers took turns.", "On the fourth flight, Wilbur remained in the air for fifty-nine seconds and travelled 852 feet, about 260 metres.", "Then a gust overturned the aircraft while it was on the ground. The machine was damaged badly enough to end that day's experiments.", "The brothers had flown, but they had not yet built an aircraft ready for ordinary travel.", "In the following years, they continued testing near Dayton. They improved the controls, made longer flights, and developed a machine that could turn, circle, and return to its starting area.", "The short journeys over the sand were the beginning of a much larger change. Powered flight would alter transport, exploration, communication, and warfare.", "The 1903 aircraft is preserved in the Smithsonian's National Air and Space Museum. Its cloth-covered wings and exposed framework look fragile beside modern airliners.", "Yet the central problems are recognisable.", "An aircraft still needs lift. It still needs power. And it still needs a way to control every movement through the air.", "The bicycle makers succeeded by working through those problems separately, then fitting their answers into one machine."], "paragraphIDs": ["the-bicycle-makers-who-taught-a-machine-to-fly-en-p-dcfe4d32fb1c", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-92c57c5f1449", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-6bdaa9e3bdd8", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-13a32a621ddb", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-b94e83b54233", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-906b0a102846", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-33e778c88569", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-23f4d7e9580e", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-7a9c4c2f279b", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-b425e6cf6670", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-a6752634d85b", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-14d7657ba349", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-f5e61d2466a5", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-1775d26c4311", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-ec88201148ed", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-ea7186f04b54", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-6af89445f8da", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-a9441dd996f3", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-c90c252e6014", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-ace393f5bbcd", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-b6178d16dcb9", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-a546290157dc", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-6af470360120", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-7432f6260170", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-860aed0eca5a", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-221c19925c0e", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-c3506e6cbc27", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-a1e4248834e0", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-4845d31e6d72", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-282cbc4ed7a7", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-093e7803dce7", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-384268d3148b", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-17b04d208b26", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-47f7035b08a0", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-5a3d26fec8f5", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-24a71f83c143", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-38a3752b0940", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-960cc4869992", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-67d90673a0bb", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-d136ff1e8900", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-b290a80a5864", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-d42b50432d52", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-8a2ff3b7cb9f", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-23707b5f896f", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-948d23f24089", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-254779d7dd26", "the-bicycle-makers-who-taught-a-machine-to-fly-en-p-affc2cf7450e"]}], "audio": null}, {"id": "the-spacecraft-that-became-a-lifeboat-en", "contentID": "the-spacecraft-that-became-a-lifeboat-en", "version": 1, "language": "en", "category": "science", "label": "SCIENCE", "title": "The Spacecraft That Became a Lifeboat", "plainTitle": "The Spacecraft That Became a Lifeboat", "description": "On 11 April 1970, three astronauts left Earth for the Moon.", "deck": "On 11 April 1970, three astronauts left Earth for the Moon.", "place": "Science", "minutes": 7, "coverURL": "content/the-spacecraft-that-became-a-lifeboat-en/v1/cover.jpg", "alt": "Illustration for The Spacecraft That Became a Lifeboat", "note": "NASA: Apollo 13 mission details; NASA: Apollo 13 mission operations report; NASA: Apollo 13 mission report.", "sources": [["NASA: Apollo 13 mission details", "https://www.nasa.gov/missions/apollo/apollo-13-mission-details/"], ["NASA: Apollo 13 mission operations report", "https://www.nasa.gov/wp-content/uploads/static/history/alsj/a13/A13_MissionOpReport.pdf"], ["NASA: Apollo 13 mission report", "https://ntrs.nasa.gov/api/citations/19710003598/downloads/19710003598.pdf"]], "chapters": [{"title": "The Spacecraft That Became a Lifeboat", "paragraphs": ["On 11 April 1970, three astronauts left Earth for the Moon.", "Jim Lovell, Fred Haise, and Jack Swigert were travelling aboard Apollo 13. Lovell and Haise were supposed to explore the lunar surface, while Swigert remained in orbit above them.", "Their spacecraft had been divided into parts because each part had a different job.", "The command module, Odyssey, carried the crew and would bring them through Earth's atmosphere at the end of the mission. Attached to it was a service module carrying systems such as fuel cells and oxygen tanks.", "The lunar module, Aquarius, was designed to take two astronauts down to the Moon and lift them back into lunar orbit.", "Together, the modules made a machine capable of a journey no single part could complete alone.", "Two days after launch, the crew were far from Earth when an oxygen tank in the service module exploded.", "Warning lights appeared. Readings changed. Lovell saw gas escaping into space.", "The trouble was much worse than one faulty instrument.", "The fuel cells used oxygen and hydrogen to produce electricity. They also produced water. Losing oxygen threatened the spacecraft's power supply as well as its life-support resources.", "A mission intended to land on the Moon became a mission to get home.", "There was no rescue spacecraft waiting nearby. Whatever the astronauts used would have to be something already aboard.", "Mission Control in Houston worked with the crew to understand the damage. Controllers had to make decisions using information sent over radio from a spacecraft more than a day's travel from safety.", "Odyssey needed to be shut down to preserve the power remaining in its batteries. Those batteries would be essential during the return through Earth's atmosphere.", "The astronauts moved into Aquarius.", "The lunar module had become a lifeboat.", "But it had been designed for two people during a limited part of a normal mission. It now had to support three people for much longer while the damaged spacecraft travelled back to Earth.", "Every available resource mattered.", "Electricity had to be saved. Water had to be rationed, partly because it was needed to cool equipment. Systems that normally kept the cabin comfortable were turned off.", "The spacecraft became cold. Moisture collected inside. Sleeping was difficult, and the men had little room to move.", "Then another problem appeared in the air they were breathing.", "People breathe in oxygen and breathe out carbon dioxide. A spacecraft cannot simply open a window to let used air escape. It has to remove carbon dioxide from its closed cabin.", "Apollo used containers of lithium hydroxide, a chemical that absorbed carbon dioxide. Aquarius carried containers for its planned two-person journey, but now three people were using up that capacity.", "Odyssey carried additional containers.", "Unfortunately, the command module's square containers did not fit the lunar module's round connections.", "The crew had the needed chemical. The obstacle was getting air to flow through it.", "Engineers on Earth assembled a solution using materials available aboard the spacecraft. These included plastic bags, cardboard, a spacesuit hose, and tape.", "They built and checked the arrangement on the ground, then explained the steps to the astronauts by radio. The crew made an adapter that directed air through the command module's containers.", "Carbon dioxide levels fell.", "The improvised equipment was not a decorative addition or a clever experiment for later. It was part of keeping the cabin usable during the journey home.", "The spacecraft also needed the right route.", "It could not stop and reverse direction like a car on a road. Its speed and position had to be changed with carefully planned engine burns.", "Apollo 13 passed around the Moon. The crew saw the world they would no longer land on, then began the long return toward Earth.", "Aquarius's engine helped adjust the path. Each burn had to be calculated so that the spacecraft would reach Earth's atmosphere at a suitable angle.", "Too shallow an approach could fail to bring it safely down. Too steep an approach would create dangerous heating and forces.", "Controllers also had to plan how to restart Odyssey using the limited power still available. The command module's equipment had been cold and inactive for days.", "On the final approach, the damaged service module was released. The astronauts could finally see the extent of the destruction outside their cabin. A large part of its outer structure was missing.", "Then they left Aquarius and prepared Odyssey for re-entry.", "Aquarius could keep them alive in space, but it did not have the command module's heat shield. It could not carry them safely through the atmosphere.", "The lifeboat had to be abandoned before the last part of the rescue.", "Odyssey separated from it and entered the air surrounding Earth.", "For several minutes, the radio connection was lost as the hot gas around the capsule interfered with communication. Mission Control could not hurry the capsule or shorten that silence.", "The signal returned.", "Parachutes opened, and on 17 April the crew splashed down in the Pacific Ocean.", "All three astronauts had survived.", "The investigation traced the accident to damage and events involving the oxygen tank before the mission, including problems during ground testing. Equipment and procedures were changed for later flights.", "Apollo 13 did not achieve its planned landing. It did reveal how much a space mission depended on people understanding the machinery well enough to use it in an emergency.", "The small module built to land two people on the Moon had instead helped bring three people back to Earth.", "Odyssey's heat shield completed a journey Aquarius could never finish.", "Neither spacecraft alone was enough. Together with the work of the crew and the teams on the ground, their remaining systems provided a route home."], "paragraphIDs": ["the-spacecraft-that-became-a-lifeboat-en-p-fa5b9e0807ea", "the-spacecraft-that-became-a-lifeboat-en-p-39b450531bff", "the-spacecraft-that-became-a-lifeboat-en-p-aeefec70c252", "the-spacecraft-that-became-a-lifeboat-en-p-7723913db256", "the-spacecraft-that-became-a-lifeboat-en-p-06c6a1a04758", "the-spacecraft-that-became-a-lifeboat-en-p-8b20d5d116b5", "the-spacecraft-that-became-a-lifeboat-en-p-9ba5f2e2ac69", "the-spacecraft-that-became-a-lifeboat-en-p-211d8887cf9e", "the-spacecraft-that-became-a-lifeboat-en-p-a43ea30d02bc", "the-spacecraft-that-became-a-lifeboat-en-p-06ade219df18", "the-spacecraft-that-became-a-lifeboat-en-p-0068213488f7", "the-spacecraft-that-became-a-lifeboat-en-p-10ab706f5688", "the-spacecraft-that-became-a-lifeboat-en-p-3415dbd11c66", "the-spacecraft-that-became-a-lifeboat-en-p-505c527dbcfd", "the-spacecraft-that-became-a-lifeboat-en-p-046196e25f8c", "the-spacecraft-that-became-a-lifeboat-en-p-6402cc24425c", "the-spacecraft-that-became-a-lifeboat-en-p-d4c4a2ea73ce", "the-spacecraft-that-became-a-lifeboat-en-p-62af4695d750", "the-spacecraft-that-became-a-lifeboat-en-p-84bd2ec6ddfd", "the-spacecraft-that-became-a-lifeboat-en-p-8a3177d8d361", "the-spacecraft-that-became-a-lifeboat-en-p-5eac18e26a5c", "the-spacecraft-that-became-a-lifeboat-en-p-4e4d17eb3ac3", "the-spacecraft-that-became-a-lifeboat-en-p-e2e69dabb53c", "the-spacecraft-that-became-a-lifeboat-en-p-710dece77be8", "the-spacecraft-that-became-a-lifeboat-en-p-560089635f79", "the-spacecraft-that-became-a-lifeboat-en-p-fe3ba7cd557a", "the-spacecraft-that-became-a-lifeboat-en-p-8a8b1c3acd1c", "the-spacecraft-that-became-a-lifeboat-en-p-358f1e4f7e28", "the-spacecraft-that-became-a-lifeboat-en-p-fece43609525", "the-spacecraft-that-became-a-lifeboat-en-p-d47e0c27f15e", "the-spacecraft-that-became-a-lifeboat-en-p-d3e74bd3983e", "the-spacecraft-that-became-a-lifeboat-en-p-a1ec3e65b664", "the-spacecraft-that-became-a-lifeboat-en-p-50e01080e494", "the-spacecraft-that-became-a-lifeboat-en-p-9371b317ec8a", "the-spacecraft-that-became-a-lifeboat-en-p-742774714bdb", "the-spacecraft-that-became-a-lifeboat-en-p-0cdd9ec1e8ff", "the-spacecraft-that-became-a-lifeboat-en-p-d23ccfcfe0ef", "the-spacecraft-that-became-a-lifeboat-en-p-f2ccecdebb84", "the-spacecraft-that-became-a-lifeboat-en-p-976188b30172", "the-spacecraft-that-became-a-lifeboat-en-p-c9963489972a", "the-spacecraft-that-became-a-lifeboat-en-p-07042ed81112", "the-spacecraft-that-became-a-lifeboat-en-p-e1efc00a7fba", "the-spacecraft-that-became-a-lifeboat-en-p-4b5d4b76fec3", "the-spacecraft-that-became-a-lifeboat-en-p-ef3925ae0868", "the-spacecraft-that-became-a-lifeboat-en-p-ec0762d09eb3", "the-spacecraft-that-became-a-lifeboat-en-p-c8e4fbc47ade", "the-spacecraft-that-became-a-lifeboat-en-p-51a92b73f8d9", "the-spacecraft-that-became-a-lifeboat-en-p-c30f489c92ce", "the-spacecraft-that-became-a-lifeboat-en-p-c1a1e74b1620", "the-spacecraft-that-became-a-lifeboat-en-p-04c8de5b0feb"]}], "audio": null}, {"id": "three-landings-on-one-comet-en", "contentID": "three-landings-on-one-comet-en", "version": 1, "language": "en", "category": "science", "label": "SCIENCE", "title": "Three Landings on One Comet", "plainTitle": "Three Landings on One Comet", "description": "On 2 March 2004, a spacecraft began a journey that would last more than ten years.", "deck": "On 2 March 2004, a spacecraft began a journey that would last more than ten years.", "place": "Science", "minutes": 6, "coverURL": "content/three-landings-on-one-comet-en/v1/cover.jpg", "alt": "Illustration for Three Landings on One Comet", "note": "ESA: The Rosetta mission; ESA: Three touchdowns; ESA: Reconstructing Philae's trajectory; ESA: Finding Philae.", "sources": [["ESA: The Rosetta mission", "https://www.esa.int/Science_Exploration/Space_Science/Rosetta"], ["ESA: Three touchdowns", "https://www.esa.int/Science_Exploration/Space_Science/Rosetta/Three_touchdowns_for_Rosetta_s_lander"], ["ESA: Reconstructing Philae's trajectory", "https://www.esa.int/ESA_Multimedia/Images/2015/04/Reconstructing_Philae_s_trajectory"], ["ESA: Finding Philae", "https://blogs.esa.int/rosetta/2016/09/28/the-story-behind-finding-philae/"]], "chapters": [{"title": "Three Landings on One Comet", "paragraphs": ["On 2 March 2004, a spacecraft began a journey that would last more than ten years.", "It was called Rosetta. Attached to it was a smaller machine, Philae, with legs that would eventually stand on a comet.", "Comets were valuable targets because they preserved material from the early Solar System. Their ice, dust, and rocky ingredients could help scientists study the conditions in which planets had formed.", "But visiting one was difficult.", "A comet did not sit in a fixed place waiting for a spacecraft. It travelled around the Sun, sometimes at great speed, while its activity changed as sunlight warmed it.", "Rosetta had to reach its destination and match its motion. Merely crossing the comet's path would produce a brief encounter. Following it required arriving with the right position and speed.", "The mission used flybys of Earth and Mars to change Rosetta's course and speed. During these manoeuvres, the spacecraft exchanged a tiny amount of energy with moving planets.", "The planets scarcely noticed. For Rosetta, the assistance was crucial.", "Part of the journey carried it so far from the Sun that conserving energy became essential. Rosetta spent more than two years in hibernation before waking in January 2014.", "Its destination was Comet 67P/Churyumov–Gerasimenko.", "As the spacecraft approached, the comet's shape became clearer. Instead of a simple ball, it had two large lobes joined by a narrow region. Cliffs, pits, boulders, and rough surfaces covered it.", "There was no smooth runway for Philae.", "Rosetta arrived in August 2014. Before sending down the lander, the team studied the comet to choose a location. They needed ground that was reasonably safe and enough sunlight for Philae's solar panels.", "Those requirements did not always favour the same place. A location with good sunlight might have dangerous terrain. A sheltered location could leave the lander without enough power.", "The comet was also turning. The chosen site moved with that rotation, so the timing and path of descent had to account for a landing place that would not stay still.", "Philae could not be steered like a helicopter. Once released, it would fall toward the comet under the weak pull of gravity.", "Weak gravity created a surprising difficulty.", "On Earth, gravity holds a landed machine firmly against the ground. On a small comet, the downward pull is much weaker. A gentle landing could still make a machine bounce away.", "Philae therefore carried equipment intended to secure it. Harpoons would fire into the surface, and screws in its feet were meant to help it grip.", "On 12 November 2014, Rosetta released the lander.", "For about seven hours, Philae descended. Rosetta continued flying nearby, carrying signals between the lander and Earth.", "Messages took many minutes to cross the distance. By the time controllers learned something had happened, that moment was already in the past.", "Philae touched the comet.", "Its harpoons did not fire.", "The lander bounced.", "Because gravity was so weak, the bounce lasted far longer than an ordinary bounce on Earth. Philae travelled across the comet before touching it again.", "It bounced a second time and finally settled at a third location.", "The machine had landed, but it was no longer where the team intended. It stood in an awkward position, with much of its surroundings blocking sunlight.", "That made its battery a deadline.", "The first battery had been charged before separation. Once its energy was exhausted, the solar panels would need enough light to keep the lander working.", "At the unexpected landing site, that supply was limited.", "The team put the available hours to work. Philae measured its surroundings and returned images and scientific information. Its instruments examined properties of the surface and sampled material around the lander.", "Scientists had to interpret the results carefully. An instrument's position mattered. A measurement made beside a shaded cliff meant something different from one made on the open surface originally chosen.", "After roughly sixty hours of work, the lander ran short of power and became silent.", "Rosetta remained active.", "It followed the comet as it moved closer to the Sun. Warming ice released gas, carrying dust into space. Rosetta could observe changes that a fast flyby would have missed.", "Philae briefly made contact again in June 2015 as conditions changed, but a dependable continuing connection was not established.", "Meanwhile, the search for its final location continued.", "Researchers used images, timing, magnetic measurements, and other information to reconstruct the bounces. Knowing where Philae stood was part of understanding its data.", "In September 2016, Rosetta photographed the lander among the comet's rough terrain. Its tilted body and extended legs could finally be recognised in the images.", "The small machine had been found.", "Later that month, Rosetta's own mission ended with a controlled descent to the comet. As it approached, it collected more close-range information before communication stopped.", "The mission had not unfolded exactly as planned. Philae's anchor system failed, the lander bounced, and the useful surface work was shortened by shadow.", "Yet a spacecraft had followed a comet through changing seasons of sunlight, and a lander had sent measurements from its surface for the first time.", "The scientists received more than spectacular pictures. They received evidence that would take years to study, including information about the comet's shape, chemistry, gases, and dust.", "Philae's three touchdowns also revealed something about exploration on small worlds.", "Landing was only the first part of the problem.", "Remaining landed was another."], "paragraphIDs": ["three-landings-on-one-comet-en-p-5660cd0a5a07", "three-landings-on-one-comet-en-p-f2442982787f", "three-landings-on-one-comet-en-p-8ee100e87523", "three-landings-on-one-comet-en-p-04e1b28bd0a9", "three-landings-on-one-comet-en-p-9cf7765da66f", "three-landings-on-one-comet-en-p-dc9a388593c0", "three-landings-on-one-comet-en-p-03dbbb907305", "three-landings-on-one-comet-en-p-0d726a63dc66", "three-landings-on-one-comet-en-p-4a14e41b619e", "three-landings-on-one-comet-en-p-b73d6b9ad5ab", "three-landings-on-one-comet-en-p-070c589499d3", "three-landings-on-one-comet-en-p-b3069221c157", "three-landings-on-one-comet-en-p-f631021c0e67", "three-landings-on-one-comet-en-p-f4a75092bc59", "three-landings-on-one-comet-en-p-603b8b6b734d", "three-landings-on-one-comet-en-p-bf332e813fcc", "three-landings-on-one-comet-en-p-a3ec31491395", "three-landings-on-one-comet-en-p-a91ccb99fb96", "three-landings-on-one-comet-en-p-da808f7fdd30", "three-landings-on-one-comet-en-p-8c5840d9b9b6", "three-landings-on-one-comet-en-p-729faf547422", "three-landings-on-one-comet-en-p-4a5beff56e19", "three-landings-on-one-comet-en-p-60414e5489b8", "three-landings-on-one-comet-en-p-22a049377aea", "three-landings-on-one-comet-en-p-d516b9a001cf", "three-landings-on-one-comet-en-p-82e4aab18680", "three-landings-on-one-comet-en-p-36259538bb28", "three-landings-on-one-comet-en-p-0d3dd34b99b8", "three-landings-on-one-comet-en-p-c0ae06278d69", "three-landings-on-one-comet-en-p-18f4c8a5547e", "three-landings-on-one-comet-en-p-0b323e7bcd5f", "three-landings-on-one-comet-en-p-296fa36f5890", "three-landings-on-one-comet-en-p-1b808d645c75", "three-landings-on-one-comet-en-p-ad6b456e3eca", "three-landings-on-one-comet-en-p-abf40dbfe928", "three-landings-on-one-comet-en-p-c6ebe3f9c85a", "three-landings-on-one-comet-en-p-99cd4c8fb419", "three-landings-on-one-comet-en-p-20a5d3c52d8d", "three-landings-on-one-comet-en-p-0b110521bf8c", "three-landings-on-one-comet-en-p-6a73fe5f9fb8", "three-landings-on-one-comet-en-p-0c910f9311e9", "three-landings-on-one-comet-en-p-d4eed3527964", "three-landings-on-one-comet-en-p-485a537f27c0", "three-landings-on-one-comet-en-p-23437f638070", "three-landings-on-one-comet-en-p-65a845c4993b", "three-landings-on-one-comet-en-p-81e699e4d052", "three-landings-on-one-comet-en-p-ce0f5a88f033", "three-landings-on-one-comet-en-p-f3decb83d5a7"]}], "audio": null}, {"id": "the-warship-that-could-not-stay-upright-en", "contentID": "the-warship-that-could-not-stay-upright-en", "version": 1, "language": "en", "category": "history", "label": "HISTORY", "title": "The Warship That Could Not Stay Upright", "plainTitle": "The Warship That Could Not Stay Upright", "description": "On 10 August 1628, people gathered beside Stockholm's harbour to watch a new warship sail.", "deck": "On 10 August 1628, people gathered beside Stockholm's harbour to watch a new warship sail.", "place": "History", "minutes": 6, "coverURL": "content/the-warship-that-could-not-stay-upright-en/v1/cover.jpg", "alt": "Illustration for The Warship That Could Not Stay Upright", "note": "Vasa Museum: Facts about Vasa; Vasa Museum: The disaster; Vasa Museum: The salvage; Vasa Museum: Excavation; Vasa Museum: Conservation. The stability explanation describes the physical principle rather than a modern calculation made by Vasa's builders.", "sources": [["Vasa Museum: Facts about Vasa", "https://www.vasamuseet.se/en/explore/vasa-history/facts-about-vasa"], ["Vasa Museum: The disaster", "https://www.vasamuseet.se/en/explore/vasa-history/disaster"], ["Vasa Museum: The salvage", "https://www.vasamuseet.se/besok/audioguide/audioguide-english/textversion/10.-the-successfull-salvage"], ["Vasa Museum: Excavation", "https://www.vasamuseet.se/en/explore/vasa-history/excavation"], ["Vasa Museum: Conservation", "https://www.vasamuseet.se/en/explore/research/conservation"]], "chapters": [{"title": "The Warship That Could Not Stay Upright", "paragraphs": ["On 10 August 1628, people gathered beside Stockholm's harbour to watch a new warship sail.", "Vasa had taken about two years to build. Carpenters had shaped great oak timbers into a hull, rope makers had supplied rigging, and carvers had covered parts of the ship with painted figures.", "The decoration announced the power of Sweden's king, Gustav II Adolf. The cannon were intended to make that power very real.", "Sweden was fighting for influence around the Baltic Sea. A heavily armed warship could attack enemy vessels, protect important routes, and carry soldiers.", "Vasa's designers were experienced craftsmen. But the ship was unusually ambitious, and they did not possess the modern calculations that allow engineers to predict a hull's stability before building it.", "They worked with proportions, practical experience, and methods passed between shipbuilders.", "The result was magnificent to look at.", "It was also dangerously unbalanced.", "A floating ship has two important centres. One is the centre of gravity, related to where its weight is concentrated. The other is the centre of buoyancy, related to the water its hull pushes aside.", "When a well-designed ship tilts, the shape of the submerged hull changes. The support of the water shifts in a way that helps bring the ship upright again.", "Vasa carried too much weight high above the water compared with the size and shape of the hull below it. Its upper structure and guns contributed to the problem.", "Heavy stones in the hold served as ballast, helping lower the centre of gravity. But more ballast was not an unlimited remedy. Extra weight also pushed the hull deeper into the water.", "Before the voyage, a stability test gave a warning. Men ran across the deck from one side to the other, setting the ship rocking. The test was stopped because its movement became alarming.", "The warning did not lead to a successful rebuilding before departure.", "Vasa set out with crew members and guests aboard. Some sailors' families had been allowed to join the beginning of the maiden voyage before leaving the ship farther along its route.", "Only a few sails were raised.", "A gust pushed against them. Vasa leaned, then recovered.", "A stronger gust followed.", "This time the ship tilted far enough for the open lower gunports to reach the water.", "The ports were openings through which cannon could fire. During the departure they had been left open. Now they became openings through which the harbour entered the ship.", "Water pouring inside added weight and made the vessel harder to right. Orders to release the sails and close the gunports came too late.", "Within minutes, Vasa sank.", "Small boats nearby rescued people, and some survivors held onto parts of the masts that remained above the surface. Around thirty people died.", "The great ship had sailed for only about twenty minutes.", "An investigation followed. It was tempting to seek one simple mistake, but the disaster involved the ship's proportions, its weight, the warning before departure, and the open gunports.", "Closing those ports might have prevented that immediate sinking. It would not have made the ship's basic design stable.", "Vasa remained beneath the harbour.", "Some cannon were recovered in the seventeenth century using diving equipment, but raising the whole vessel was beyond the practical means of the time.", "The water had conditions that helped preserve its wood. The low salinity of the Baltic discouraged the wood-boring shipworms that destroy many wrecks in saltier seas.", "That did not mean the ship stayed completely unchanged. Iron fittings corroded, and chemical processes affected the timber. But much of its structure survived.", "In the twentieth century, Anders Franzén searched for the wreck. In 1956, he located it.", "Divers then faced an enormous engineering task. They excavated tunnels beneath the hull so that lifting cables could be passed underneath. Lifting vessels gradually raised the ship in stages.", "On 24 April 1961, Vasa returned to daylight.", "The rescue of the ship created a new problem immediately. Waterlogged old wood could shrink and crack if it dried without treatment.", "Conservators kept it wet while developing a way to support the weakened timber. Over many years, they treated it with polyethylene glycol, a material that could help replace water within the wood.", "Archaeologists recovered shoes, tools, clothing, household objects, and equipment. These possessions revealed the daily lives of people who had boarded a working ship in 1628.", "The polished story of royal power became something more complicated: a record of sailors, craftsmen, engineering decisions, and a disaster witnessed from shore.", "Vasa eventually received a purpose-built museum.", "Its preservation continued, because saving an old ship did not end when it left the water. The timber needed support, suitable humidity, careful inspection, and control of damaging chemical changes.", "The warship never fought the battles for which it had been made.", "Instead, it became an unusually complete example of seventeenth-century shipbuilding.", "Its towering stern and crowded gun decks still show the ambition of its builders. Its short first voyage shows why a vessel's impressive appearance cannot tell anyone whether it will remain upright."], "paragraphIDs": ["the-warship-that-could-not-stay-upright-en-p-647c7615d024", "the-warship-that-could-not-stay-upright-en-p-491bf713ae68", "the-warship-that-could-not-stay-upright-en-p-a1dbd6e4bcb8", "the-warship-that-could-not-stay-upright-en-p-b63c96ff2e53", "the-warship-that-could-not-stay-upright-en-p-d6e4d9cb5dcd", "the-warship-that-could-not-stay-upright-en-p-9ed8dc18a776", "the-warship-that-could-not-stay-upright-en-p-e503345fb662", "the-warship-that-could-not-stay-upright-en-p-f9e139f890a7", "the-warship-that-could-not-stay-upright-en-p-be6226e801db", "the-warship-that-could-not-stay-upright-en-p-020c7d4010c1", "the-warship-that-could-not-stay-upright-en-p-9223ffc93e19", "the-warship-that-could-not-stay-upright-en-p-ae84c80be209", "the-warship-that-could-not-stay-upright-en-p-cc0ea75f3ec1", "the-warship-that-could-not-stay-upright-en-p-c31962f11a2a", "the-warship-that-could-not-stay-upright-en-p-e6e2aaefdde6", "the-warship-that-could-not-stay-upright-en-p-760b43424a95", "the-warship-that-could-not-stay-upright-en-p-912fd1c3f6d6", "the-warship-that-could-not-stay-upright-en-p-3797b4f57ebe", "the-warship-that-could-not-stay-upright-en-p-cbb2f40561df", "the-warship-that-could-not-stay-upright-en-p-2c32c9e83073", "the-warship-that-could-not-stay-upright-en-p-979eccdffe04", "the-warship-that-could-not-stay-upright-en-p-f4d998d7f4fe", "the-warship-that-could-not-stay-upright-en-p-ff001c967c36", "the-warship-that-could-not-stay-upright-en-p-f70252b820ac", "the-warship-that-could-not-stay-upright-en-p-18c25ad67d1f", "the-warship-that-could-not-stay-upright-en-p-38d607877d9c", "the-warship-that-could-not-stay-upright-en-p-cf8bab502aa0", "the-warship-that-could-not-stay-upright-en-p-c66e59e47d23", "the-warship-that-could-not-stay-upright-en-p-3f560eaaf850", "the-warship-that-could-not-stay-upright-en-p-10b87b81bf5d", "the-warship-that-could-not-stay-upright-en-p-ac351cd74f36", "the-warship-that-could-not-stay-upright-en-p-8fb323bc45dd", "the-warship-that-could-not-stay-upright-en-p-6197875aee20", "the-warship-that-could-not-stay-upright-en-p-f7fd63bc3183", "the-warship-that-could-not-stay-upright-en-p-c06dc8d2e6d7", "the-warship-that-could-not-stay-upright-en-p-1d32a14f0ba0", "the-warship-that-could-not-stay-upright-en-p-a8ccf65b7adc", "the-warship-that-could-not-stay-upright-en-p-0ccdc1d4c59d", "the-warship-that-could-not-stay-upright-en-p-43b6777bbda1", "the-warship-that-could-not-stay-upright-en-p-38057c460d6c", "the-warship-that-could-not-stay-upright-en-p-82623d7e0b04", "the-warship-that-could-not-stay-upright-en-p-f767d1631754"]}], "audio": null}, {"id": "the-girl-and-the-sea-beneath-the-cliff-en", "contentID": "the-girl-and-the-sea-beneath-the-cliff-en", "version": 1, "language": "en", "category": "nature", "label": "NATURE", "title": "The Girl and the Sea Beneath the Cliff", "plainTitle": "The Girl and the Sea Beneath the Cliff", "description": "At Lyme Regis, on England's southern coast, the sea worked on the cliffs every day.", "deck": "At Lyme Regis, on England's southern coast, the sea worked on the cliffs every day.", "place": "Nature", "minutes": 6, "coverURL": "content/the-girl-and-the-sea-beneath-the-cliff-en/v1/cover.jpg", "alt": "Illustration for The Girl and the Sea Beneath the Cliff", "note": "Natural History Museum: Mary Anning's life and discoveries; Natural History Museum: Her fossils; Natural History Museum: Ichthyosaurs; Natural History Museum: Plesiosaurs. Accounts differ over the exact year of the first skull's discovery; the narrative avoids assigning it a single disputed date.", "sources": [["Natural History Museum: Mary Anning's life and discoveries", "https://www.nhm.ac.uk/discover/mary-anning-unsung-hero.html"], ["Natural History Museum: Her fossils", "https://www.nhm.ac.uk/discover/mary-anning-fossils.html"], ["Natural History Museum: Ichthyosaurs", "https://www.nhm.ac.uk/discover/what-is-an-ichthyosaur.html"], ["Natural History Museum: Plesiosaurs", "https://www.nhm.ac.uk/discover/what-is-a-plesiosaur.html"]], "chapters": [{"title": "The Girl and the Sea Beneath the Cliff", "paragraphs": ["At Lyme Regis, on England's southern coast, the sea worked on the cliffs every day.", "Waves struck their base. Rain loosened the layers above. After storms, pieces of rock lay on the beach where there had been clear ground before.", "Inside those rocks were remains of another sea, one that had covered the area roughly two hundred million years earlier.", "Mary Anning grew up beside the cliffs.", "Her family had little money. Her father, Richard, was a carpenter who also collected fossils to sell. Visitors bought curled ammonites and pointed belemnites as curiosities.", "Mary and her brother Joseph learned to search the beach. A piece of fossil exposed in a rock could mean something worth selling, and selling it could help pay for food.", "But finding a fossil was only the beginning.", "The object had to be removed without breaking it. A hammer used carelessly could destroy the evidence. A valuable skeleton might remain hidden beneath heavy rock, with only a small part showing.", "The cliffs themselves were dangerous. The same falls that exposed fossils could bury a collector beneath them.", "Richard died in 1810, leaving the family in difficult circumstances.", "Early in the following years, Joseph found an unusual fossil skull. Mary went on to uncover the associated skeleton, a job that required prolonged work rather than one dramatic swing of a hammer.", "The creature was about five metres long.", "Its long jaws and large eye sockets were unlike the familiar shells sold to visitors. Scientists examined the remains and argued about the animal to which they had belonged.", "It became an important early specimen in the scientific study of ichthyosaurs.", "An ichthyosaur was a marine reptile. It was not a dinosaur, and it was not a fish, even though its body was adapted for moving through water.", "The distinction mattered. Scientists were beginning to reconstruct groups of animals that no longer existed.", "Some people still explained unfamiliar fossils as the remains of creatures living in undiscovered places. Increasing evidence showed that many fossil animals had vanished altogether.", "Extinction meant Earth's living world had changed profoundly.", "Mary continued collecting. She learned anatomy, compared bones, read scientific writing, and prepared specimens with care. Her work increasingly required recognising what a fragment belonged to and where other parts might be found.", "In 1823, she uncovered another remarkable skeleton.", "It had four flippers, a small head, and a very long neck.", "This was a plesiosaur.", "The arrangement looked so unfamiliar that Georges Cuvier, one of Europe's leading experts on fossil animals, initially questioned whether it was genuine.", "A long neck attached to that body could seem like a mistake made by combining remains from different animals.", "The position of the bones was therefore important. An articulated skeleton, with its parts preserved in their natural arrangement, provided much stronger evidence than a box of loose pieces.", "Further examination convinced Cuvier that the specimen was real.", "Mary's discovery supplied a body plan scientists could study. Plesiosaurs were no longer merely an incomplete collection of difficult bones.", "Fossils also carried information about the environment in which they had lived.", "The rock layers at Lyme Regis contained ammonites, marine reptiles, and other sea creatures. Those remains showed that a beach below cliffs had once been part of a seabed.", "Sediment had covered dead organisms. Over immense spans of time, buried material and minerals preserved traces of their bodies while the surrounding sediment became rock.", "Later movements of Earth's crust and erosion brought those layers to the surface.", "Mary did not know every modern detail of these processes. But the evidence she uncovered helped make the ancient environment visible.", "In 1828, she found remains of a flying reptile, a pterosaur, the first such discovery outside Germany.", "Her finds were no longer only about animals swimming in a lost sea. They also revealed creatures that had flown above it.", "Other observations opened smaller windows into ancient life. Fossilised dung, called coprolites, could preserve pieces of food. What seemed an unappealing object could help identify what an animal had eaten.", "The scientific importance of Mary's work did not remove the social barriers around her.", "She was a woman from a poor family, earning money by selling specimens. Scientific societies and formal education offered far more opportunities to wealthy men.", "The Geological Society of London did not admit women as fellows during her lifetime. Researchers who bought her fossils sometimes published descriptions without giving her appropriate credit.", "Yet collecting and preparing were central parts of the discovery. A skeleton destroyed during extraction would never reach a scientist's desk.", "Henry De la Beche, a geologist who knew Mary, painted a reconstruction of the ancient Dorset sea in 1830. His picture included marine reptiles based on fossil evidence. Prints were sold to help support her.", "The image allowed people to connect separate skeletons with a shared environment.", "Mary died in 1847, aged forty-seven. She had not become wealthy, despite her extraordinary contributions.", "Her specimens remained.", "They were studied again as scientific knowledge grew. Some can still be seen in museum galleries, where their flippers, jaws, and long necks continue to explain a world far older than the buildings containing them.", "The cliffs at Lyme Regis are still eroding.", "The sea continues uncovering the seabed of another age. Mary Anning helped turn what emerged from that rock into evidence of real animals, real environments, and changes stretching across millions of years."], "paragraphIDs": ["the-girl-and-the-sea-beneath-the-cliff-en-p-81dc17c7df44", "the-girl-and-the-sea-beneath-the-cliff-en-p-5b1d1ab84569", "the-girl-and-the-sea-beneath-the-cliff-en-p-f49c525f807a", "the-girl-and-the-sea-beneath-the-cliff-en-p-e724d2803db8", "the-girl-and-the-sea-beneath-the-cliff-en-p-a650b81f6294", "the-girl-and-the-sea-beneath-the-cliff-en-p-271e518d074f", "the-girl-and-the-sea-beneath-the-cliff-en-p-fd7e4eb5ac70", "the-girl-and-the-sea-beneath-the-cliff-en-p-54e498768af4", "the-girl-and-the-sea-beneath-the-cliff-en-p-a9cff53c6d51", "the-girl-and-the-sea-beneath-the-cliff-en-p-88a622b2d1f6", "the-girl-and-the-sea-beneath-the-cliff-en-p-e097d2b08890", "the-girl-and-the-sea-beneath-the-cliff-en-p-f7b0ca9b5601", "the-girl-and-the-sea-beneath-the-cliff-en-p-b5200f47e500", "the-girl-and-the-sea-beneath-the-cliff-en-p-ed334f4d1177", "the-girl-and-the-sea-beneath-the-cliff-en-p-43612243c4a7", "the-girl-and-the-sea-beneath-the-cliff-en-p-aeb485cae596", "the-girl-and-the-sea-beneath-the-cliff-en-p-4618b4620bcd", "the-girl-and-the-sea-beneath-the-cliff-en-p-1c3c696df8ac", "the-girl-and-the-sea-beneath-the-cliff-en-p-dde0dfcaefb3", "the-girl-and-the-sea-beneath-the-cliff-en-p-4dcd032c829d", "the-girl-and-the-sea-beneath-the-cliff-en-p-7ec0e1bfe168", "the-girl-and-the-sea-beneath-the-cliff-en-p-fe14c6d6bfd3", "the-girl-and-the-sea-beneath-the-cliff-en-p-6c6c2e3d2ef1", "the-girl-and-the-sea-beneath-the-cliff-en-p-1649c972f783", "the-girl-and-the-sea-beneath-the-cliff-en-p-202d592f4a93", "the-girl-and-the-sea-beneath-the-cliff-en-p-4ac1c45a0911", "the-girl-and-the-sea-beneath-the-cliff-en-p-bc9e1ae2f459", "the-girl-and-the-sea-beneath-the-cliff-en-p-670cfd38d6ab", "the-girl-and-the-sea-beneath-the-cliff-en-p-923f528f48f3", "the-girl-and-the-sea-beneath-the-cliff-en-p-2c6197aba65f", "the-girl-and-the-sea-beneath-the-cliff-en-p-82d71e514510", "the-girl-and-the-sea-beneath-the-cliff-en-p-70a8bdc9e1c5", "the-girl-and-the-sea-beneath-the-cliff-en-p-27930fb2f6cb", "the-girl-and-the-sea-beneath-the-cliff-en-p-af7da377e9c7", "the-girl-and-the-sea-beneath-the-cliff-en-p-8ed7adaa28a1", "the-girl-and-the-sea-beneath-the-cliff-en-p-0b0060434af0", "the-girl-and-the-sea-beneath-the-cliff-en-p-f47a24092076", "the-girl-and-the-sea-beneath-the-cliff-en-p-98e151be916b", "the-girl-and-the-sea-beneath-the-cliff-en-p-229b3a015a67", "the-girl-and-the-sea-beneath-the-cliff-en-p-38bc59f9ee1c", "the-girl-and-the-sea-beneath-the-cliff-en-p-bc2b4aa73f5d", "the-girl-and-the-sea-beneath-the-cliff-en-p-75b9d6dc63a4", "the-girl-and-the-sea-beneath-the-cliff-en-p-c25ffe71a132", "the-girl-and-the-sea-beneath-the-cliff-en-p-40bd1cb1189e", "the-girl-and-the-sea-beneath-the-cliff-en-p-f3505f62390b", "the-girl-and-the-sea-beneath-the-cliff-en-p-b27fdba97cde"]}], "audio": null}];
